#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY: without it GC collects this NewObject'ed UObject and
	// AddPoints() later dereferences freed memory (shipping crash).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker in Source/PixelArena/ArenaGameMode.h was a raw, non-UPROPERTY pointer to a NewObject'ed UObject. The garbage collector collected it (log: 'Collecting garbage: 412 objects purged' at 21:05:13, crash at 21:05:27 on the next OnGoalScored), and UArenaScoreTracker::AddPoints() dereferenced freed memory (Unhandled Exception: EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff at ArenaScoreTracker.cpp:18, called from ArenaGameMode.cpp:36). Fixed by declaring it as UPROPERTY() TObjectPtr<UArenaScoreTracker> so GC roots it. Editor builds mask this with different GC timing.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was not cooked into the package: DefaultGame.ini had bCookAll=False and DirectoriesToAlwaysCook only listed /Game/Data/Effects, so LogStreaming failed with 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', LoadObject returned null and the game fell back to gray ('Palette is null, using fallback gray'). The editor works because it loads the asset from source content. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini.",
  "fixes": [
    "Source/PixelArena/ArenaGameMode.h: ScoreTracker is now UPROPERTY() TObjectPtr<UArenaScoreTracker> (GC-rooted).",
    "Config/DefaultGame.ini: added /Game/Data/Palettes to DirectoriesToAlwaysCook."
  ],
  "assumptions": [
    "No engine on the machine, so fixes are source/config only and unverified by a rebuild.",
    "TeamIndex passed to ScoreTracker->AddPoints is assumed valid; the crash address pattern and GC log point to the dangling-object cause, not an index issue."
  ],
  "evidence": "Saved/Logs/PixelArena-shipping.log lines 4-6 (missing palette, gray fallback), line 8 (GC purge), lines 10-14 (access violation in AddPoints from OnGoalScored)."
}
